1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
scsi: bsg-lib: Fix commands without data transfer in
 bsg_transport_sg_io_fn()

Set ret to 0 after the initial permission checks to avoid leaking -EPERM
for commands without data transfer.

Link: https://lore.kernel.org/r/20210731074027.1185545-3-hch@lst.de
Fixes: 75ca56409e5b ("scsi: bsg: Move the whole request execution into the SCSI/transport handlers")
Signed-off-by: Christoph Hellwig <hch@lst.de>
Signed-off-by: Martin K. Petersen <martin.petersen@oracle.com>

Here is the root cause:
The bug was caused by the function `bsg_transport_sg_io_fn` not properly handling commands that do not involve data transfer. Specifically, the return value `ret` was not being reset to 0 after the initial permission checks, leading to the unintended leakage of the error code `-EPERM` for such commands.

Here is the patch:

 static int bsg_transport_sg_io_fn(struct request_queue *q, struct sg_io_v4 *hdr,
 		fmode_t mode, unsigned int timeout)
 {
 	struct bsg_job *job;
 	struct request *rq;
 	struct bio *bio;
 	int ret;

 	if (hdr->protocol != BSG_PROTOCOL_SCSI  ||
 	    hdr->subprotocol != BSG_SUB_PROTOCOL_SCSI_TRANSPORT)
 		return -EINVAL;
 	if (!capable(CAP_SYS_RAWIO))
 		return -EPERM;

 	rq = blk_get_request(q, hdr->dout_xfer_len ?
 			     REQ_OP_DRV_OUT : REQ_OP_DRV_IN, 0);
 	if (IS_ERR(rq))
 		return PTR_ERR(rq);
 	rq->timeout = timeout;

 	job = blk_mq_rq_to_pdu(rq);
 	job->request_len = hdr->request_len;
 	job->request = memdup_user(uptr64(hdr->request), hdr->request_len);
 	if (IS_ERR(job->request)) {
 		ret = PTR_ERR(job->request);
 		goto out_put_request;
 	}

 	if (hdr->dout_xfer_len && hdr->din_xfer_len) {
 		job->bidi_rq = blk_get_request(rq->q, REQ_OP_DRV_IN, 0);
 		if (IS_ERR(job->bidi_rq)) {
 			ret = PTR_ERR(job->bidi_rq);
 			goto out_free_job_request;
 		}

 		ret = blk_rq_map_user(rq->q, job->bidi_rq, NULL,
 				uptr64(hdr->din_xferp), hdr->din_xfer_len,
 				GFP_KERNEL);
 		if (ret)
 			goto out_free_bidi_rq;

 		job->bidi_bio = job->bidi_rq->bio;
 	} else {
 		job->bidi_rq = NULL;
 		job->bidi_bio = NULL;
 	}

+	ret = 0;
 	if (hdr->dout_xfer_len) {
 		ret = blk_rq_map_user(rq->q, rq, NULL, uptr64(hdr->dout_xferp),
 				hdr->dout_xfer_len, GFP_KERNEL);
 	} else if (hdr->din_xfer_len) {
 		ret = blk_rq_map_user(rq->q, rq, NULL, uptr64(hdr->din_xferp),
 				hdr->din_xfer_len, GFP_KERNEL);
 	}

 	if (ret)
 		goto out_unmap_bidi_rq;

 	bio = rq->bio;
 	blk_execute_rq(NULL, rq, !(hdr->flags & BSG_FLAG_Q_AT_TAIL));

 	/*
 	 * The assignments below don't make much sense, but are kept for
 	 * bug by bug backwards compatibility:
 	 */
 	hdr->device_status = job->result & 0xff;
 	hdr->transport_status = host_byte(job->result);
 	hdr->driver_status = 0;
 	hdr->info = 0;
 	if (hdr->device_status || hdr->transport_status || hdr->driver_status)
 		hdr->info |= SG_INFO_CHECK;
 	hdr->response_len = 0;

 	if (job->result < 0) {
 		/* we're only returning the result field in the reply */
 		job->reply_len = sizeof(u32);
 		ret = job->result;
 	}

 	if (job->reply_len && hdr->response) {
 		int len = min(hdr->max_response_len, job->reply_len);

 		if (copy_to_user(uptr64(hdr->response), job->reply, len))
 			ret = -EFAULT;
 		else
 			hdr->response_len = len;
 	}

 	/* we assume all request payload was transferred, residual == 0 */
 	hdr->dout_resid = 0;

 	if (job->bidi_rq) {
 		unsigned int rsp_len = job->reply_payload.payload_len;

 		if (WARN_ON(job->reply_payload_rcv_len > rsp_len))
 			hdr->din_resid = 0;
 		else
 			hdr->din_resid = rsp_len - job->reply_payload_rcv_len;
 	} else {
 		hdr->din_resid = 0;
 	}

 	blk_rq_unmap_user(bio);
 out_unmap_bidi_rq:
 	if (job->bidi_rq)
 		blk_rq_unmap_user(job->bidi_bio);
 out_free_bidi_rq:
 	if (job->bidi_rq)
 		blk_put_request(job->bidi_rq);
 out_free_job_request:
 	kfree(job->request);
 out_put_request:
 	blk_put_request(rq);
 	return ret;
 }



